    >
      <input
        data-testid="invoice-form-amount"
        placeholder="Amount"
        value={amount}
        onChange={(event) => setAmount(event.target.value)}
      />
      <button data-testid="invoice-form-submit" type="submit">
        Add invoice
      </button>
    </form>
  );
}
